/// <summary>
/// Extension of GUPItemBasePriceCalcJob
/// </summary>
[ExtensionOf(classStr(GUPItemBasePriceCalcJob))]
internal final class METGUPItemBasePriceCalcJobCls_Extension
{
    private NoYes generatePriceChangeInquiry;

}

Method.Source:
/// <summary>
/// Pack
/// </summary>
/// <returns>container value</returns>
public container pack()
{
    return SysPackExtensions::appendExtension(next pack(), classStr(METGUPItemBasePriceCalcJobCls_Extension), [generatePriceChangeInquiry]);
}

    /// <summary>
    /// Unpack
    /// </summary>
    /// <param name = "_pack">pack</param>
    /// <returns>boolean value</returns>
    public boolean unpack(container _pack)
    {
        boolean ret = next unpack(_pack);

        if (ret)
        {
            container extensionState = SysPackExtensions::findExtension(_pack, classStr(METGUPItemBasePriceCalcJobCls_Extension));

            generatePriceChangeInquiry = conPeek(extensionState, 1);
        }

        return ret;
    }

/// <summary>
/// GeneratePriceChangeInquiry
/// </summary>
/// <param name = "_generatePriceChangeInquiry">GeneratePriceChangeInquiry</param>
/// <returns>NoYesvalue</returns>
public NoYes parmGeneratePriceChangeInquiry(NoYes _generatePriceChangeInquiry = generatePriceChangeInquiry)
{
    generatePriceChangeInquiry = _generatePriceChangeInquiry;
    return generatePriceChangeInquiry;
}

    /// <summary>
    /// GeneratePriceChangeInquiry
    /// </summary>
    protected void generatePriceChangeInquiry()
    {
        next generatePriceChangeInquiry();

        if (this.parmGeneratePriceChangeInquiry())
        {
            METGeneratePriceChangeInquiryBasePriceDialog priceChangeInquiryDialog = METGeneratePriceChangeInquiryBasePriceDialog::construct();

            priceChangeInquiryDialog.init();
            priceChangeInquiryDialog.parmInBatch(false);
            priceChangeInquiryDialog.parmReportName(strFmt("@GlobalUnifiedPricingMetcash:METPriceChangeInquiryReportName", this.parmBasePriceVersionId(), this.parmSiteId()));
            priceChangeInquiryDialog.parmSiteId(this.parmSiteId());
            priceChangeInquiryDialog.parmActivationDate(this.parmCalcDate());
            priceChangeInquiryDialog.initQueryRun();

            priceChangeInquiryDialog.run();
        }
    }
